// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "in the export tab could you add a simple preview when the latex version is selecter for export"
// Changes: HTML approximation of the LaTeX output – bordered tabular for tables, align* + enumerate for the definition.
const TEX_FONT = { fontFamily: '"Latin Modern Roman", "CMU Serif", "Computer Modern", Georgia, "Times New Roman", serif' }

function LatexPreview({ preview }: { preview: TexPreview }) {
  const tt = (s: string) => <span className="font-mono text-[0.9em]">{s}</span>
  return (
    <div
      role="region"
      tabIndex={0}
      aria-label="Náhľad LaTeX výstupu"
      className="max-h-[60vh] overflow-auto rounded-xl border border-white/10 bg-white p-5 text-[15px] text-black focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400"
      style={TEX_FONT}
    >
      {preview.type === 'table' ? (
        <table className="mx-auto border-collapse">
          <tbody>
            {[preview.header, ...preview.rows].map((row, r) => (
              <tr key={r}>
                {row.map((cell, c) => (
                  <td key={c} className="border border-black px-2 py-0.5 text-center whitespace-nowrap">
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <>
          <div className="mx-auto grid w-fit grid-cols-[auto_auto] gap-x-1 gap-y-1 italic">
            {(
              [
                ['G', <span className="not-italic">(<i>N</i>, <i>T</i>, <i>P</i>, <i>S</i>)</span>],
                ['N', setOf(preview.N, tt)],
                ['T', setOf(preview.T, tt)],
                ['S', preview.S ? tt(preview.S) : '-'],
              ] as const
            ).map(([lhs, rhs]) => (
              <div key={lhs} className="contents">
                <span className="text-right">{lhs}</span>
                <span className="not-italic">= {rhs}</span>
              </div>
            ))}
          </div>
          {preview.rules.length > 0 && (
            <ol className="mt-4 list-decimal pl-8">
              {preview.rules.map((r, i) => (
                <li key={i}>
                  {tt(r.lhs)} → {r.rhs.length ? r.rhs.map((s, j) => <span key={j}>{j > 0 && ' '}{tt(s)}</span>) : <i>ε</i>}
                </li>
              ))}
            </ol>
          )}
        </>
      )}
    </div>
  )
}

function setOf(xs: string[], tt: (s: string) => ReactNode) {
  if (!xs.length) return '∅'
  return (
    <>
      {'{ '}
      {xs.map((x, i) => (
        <span key={i}>
          {i > 0 && ', '}
          {tt(x)}
        </span>
      ))}
      {' }'}
    </>
  )
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Short-lived copy confirmation for a role="status" element: cleared first so a repeat is announced again,
//          one pending timer (restarted on repeat clicks), a no-break space when the text repeats (VoiceOver skips
//          identical messages), emptied afterwards so no stale text is left for browse mode.
const COPY_STATUS_MS = 2000

function useCopyStatus() {
  const [message, setMessage] = useState('')
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  const frame = useRef(0)
  const last = useRef('')
  useEffect(
    () => () => {
      clearTimeout(timer.current)
      cancelAnimationFrame(frame.current)
    },
    [],
  )
  const report = (text: string) => {
    clearTimeout(timer.current)
    cancelAnimationFrame(frame.current)
    setMessage('')
    const next = text === last.current ? text + '\u00A0' : text
    last.current = next
    frame.current = requestAnimationFrame(() => setMessage(next))
    timer.current = setTimeout(() => setMessage(''), COPY_STATUS_MS)
  }
  return { message, report }
}
